def dehydrate_timedelta(value):
    """ Dehydrator for `timedelta` values.

    :param value:
    :type value: timedelta
    :return:
    """

    if value is None:
        return None
    if not isinstance(value, timedelta):
        raise TypeError("dehydrate_timedelta expects a timedelta instance")
    return value.total_seconds()

def dehydrate_time(value):
    """Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return: a serializable representation of the time value
    """
    if value is None:
        return None
    # If the time object provides a human‑readable string representation
    try:
        return str(value)
    except Exception:
        pass
    # Prefer explicit dictionary conversion if available
    if hasattr(value, "to_dict") and callable(value.to_dict):
        try:
            return value.to_dict()
        except Exception:
            pass
    # Fallback to the object's __dict__ (excluding private attributes)
    if hasattr(value, "__dict__"):
        try:
            return {k: v for k, v in value.__dict__.items() if not k.startswith("_")}
        except Exception:
            pass
    # As a last resort, try JSON serialisation
    try:
        import json
        return json.loads(json.dumps(value, default=str))
    except Exception:
        pass
    # If all else fails, return its string representation
    return str(value)

def dehydrate_point(value):
    """ Dehydrator for Point data.
    :param value:
    :type value: Point
    :return: list of coordinates
    """
    if value is None:
        return None
    # Try shapely / tuple based point representations
    if hasattr(value, "coords"):
        try:
            return list(value.coords[0])
        except Exception:
            pass
    try:
        return [value.x, value.y]
    except Exception:
        pass
    raise ValueError("Unsupported point representation")

def keys(self):
        """ Return the keys of the record.

        :return: list of key names
        """
        return list(self.__dict__.keys())

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is None:
        # return a copy of the mapping to avoid accidental modifications
        return dict(cls._protocol_handlers)

    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")

    handler = cls._protocol_handlers.get(protocol_version)
    if handler is not None:
        return {protocol_version: handler}
    return {}

def index(self, key):
    """ Return the index of the given item.

    :param key: a key
    :return: index
    :rtype: int
    """
    for idx, item in enumerate(self):
        if item == key:
            return idx
    raise ValueError(f"{key} is not in the list")

def values(self, *keys):
    """ Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # assume the record is stored in a dictionary-like attribute called _record
    if not hasattr(self, "_record"):
        raise AttributeError("Object does not contain a '_record' attribute")

    if not keys:
        return list(self._record.values())

    result = []
    values_list = list(self._record.values())
    for key in keys:
        if isinstance(key, int):
            try:
                result.append(values_list[key])
            except IndexError:
                raise IndexError(f"Index {key} out of range for record values")
        else:
            try:
                result.append(self._record[key])
            except KeyError:
                raise KeyError(f"Key {key!r} not found in record")
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indices provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """

    # Helper: try to find where the record's data is stored.
    # We look for common attribute names that might hold the data
    # and the corresponding keys.
    _value_attr = None
    _key_attr = None

    for attr in ('values', 'data', 'items'):
        if hasattr(self, attr):
            _value_attr = attr
            break

    for attr in ('keys', 'fields', 'field_names', 'names'):
        if hasattr(self, attr):
            _key_attr = attr
            break

    if _value_attr is None or _key_attr is None:
        raise AttributeError(
            "Record object must have attributes holding values and keys "
            "(e.g., 'values' and 'keys')")

    values = getattr(self, _value_attr)
    keys_list = getattr(self, _key_attr)

    # If values are dict-like, handle directly.
    if isinstance(values, dict):
        if not keys:
            return dict(values)         # shallow copy
        result = {}
        for k in keys:
            result[k] = values.get(k, None)
        return result

    # Assume values is an ordered sequence and keys_list is the
    # corresponding field names (must be the same length).
    if not isinstance(values, (list, tuple)):
        raise TypeError("Record values must be a dict or a sequence")

    if len(values) != len(keys_list):
        raise ValueError("Length of values and keys must match")

    if not keys:
        return dict(zip(keys_list, values))

    result = {}
    for k in keys:
        if isinstance(k, int):                       # treat as index
            if k < 0 or k >= len(values):
                raise IndexError(f"Index {k} out of bounds")
            result[keys_list[k]] = values[k]
        else:                                        # treat as field name
            if k in keys_list:
                idx = keys_list.index(k)
                result[k] = values[idx]
            else:
                result[k] = None

    return result

def discard(self, n=-1, qid=-1, dehydration_hooks=None,
                hydration_hooks=None, **handlers):
    """Appends a DISCARD message to the output queue.

    :param n: number of records to discard, default = -1 (ALL)
    :param qid: query ID to discard for, default = -1 (last query)
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    """
    if dehydration_hooks is None:
        dehydration_hooks = {}
    if hydration_hooks is None:
        hydration_hooks = {}

    # Construct the DISCARD message.
    message = {
        "type": "DISCARD",
        "n": n,
        "qid": qid,
        "dehydration_hooks": dehydration_hooks,
        "hydration_hooks": hydration_hooks,
    }

    # Append the message to the output queue.
    # The actual queue attribute name may differ; adjust as necessary.
    if hasattr(self, "_output_queue"):
        self._output_queue.append(message)
    elif hasattr(self, "output_queue"):
        self.output_queue.append(message)
    else:
        # Fallback: use a generic method if defined.
        if hasattr(self, "send"):
            self.send(message)
        else:
            raise AttributeError("No output queue or send method found to append DISCARD message.")

    # Return a Response object that will handle the server response.
    # Assume a Response class exists in the surrounding context.
    return Response(self, handlers)

def deprecated(message):
    """ Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    import warnings
    import functools

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            warnings.warn(
                f"Function {func.__name__} is deprecated: {message}",
                category=DeprecationWarning,
                stacklevel=2,
            )
            return func(*args, **kwargs)
        return wrapper

    return decorator

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    if not cmd:
        return ()
    try:
        platform = __import__("sys").platform
    except Exception:
        return cmd
    if not platform.startswith("win"):
        return cmd

    # On Windows shebang lines are ignored.  Try to read the
    # first line of the script and use the interpreter specified
    # in the shebang to build a new command line.
    try:
        with open(cmd[0], "rb") as f:
            first = f.readline().decode(errors="ignore").strip()
    except Exception:
        # If the file cannot be opened, fall back to the original command
        return cmd

    if not first.startswith("#!"):
        return cmd

    # Parse the shebang: ``#! /path/to/interpreter [args...]``.
    # shlex.split understands quoting on both POSIX and Windows.
    try:
        parts = __import__("shlex").split(first[2:].strip())
    except Exception:
        # If shlex fails, just return the original command.
        return cmd

    if not parts:
        return cmd

    # Build the new command: interpreter args ... script ... rest
    new_cmd = tuple(parts) + (cmd[0],) + cmd[1:]
    return new_cmd

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            # compute hash key, allowing key to accept either args/kwargs
            try:
                k = key(*args, **kwargs)
            except TypeError:
                k = key(args, kwargs)

            if k in cache:
                return cache[k]

            if lock is not None:
                lock.acquire()
                try:
                    if k in cache:
                        return cache[k]
                    result = func(*args, **kwargs)
                    cache[k] = result
                    return result
                finally:
                    lock.release()

            result = func(*args, **kwargs)
            cache[k] = result
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper
    return decorator

def setdefault(self, key, default=None):
    """D.setdefault(k[,d]) -> D.get(k,d), also set D[k]=d if k not in D"""
    if key in self:
        return self[key]
    self[key] = default
    return default

def get(self, key, default=None):
    """
    D.get(k[,d]) -> D[k] if k in D, else d.  d defaults to None.
    """
    try:
        return self[key]
    except KeyError:
        return default

def cachedmethod(cache, key=hashkey, lock=None):
    """Decorator to wrap a class or instance method with a memoizing
    callable that saves results in a cache.

    """
    def decorator(func):
        def wrapper(*args, **kwargs):
            cache_key = key(*args, **kwargs)
            if cache_key in cache:
                return cache[cache_key]
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

@staticmethod
def is_file_exist(file_name):
    """Check if file name exist.
    :param file_name: File name.
    :type file_name: str
    :return: Return true (exist), false (do not exist, or invalid file name)
    :rtype bool
    """
    if not isinstance(file_name, str) or not file_name:
        return False
    try:
        return os.path.isfile(file_name)
    except Exception:
        return False

@classmethod
def _reset_logging(cls):
    """Reset"""
    import logging
    # Remove all existing handlers from the root logger
    root = logging.getLogger()
    for handler in root.handlers[:]:
        root.removeHandler(handler)
    # Reconfigure the logger with default settings
    logging.basicConfig()

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    name = self.__class__.__name__
    for suffix in ("Py", "Fallback"):
        if name.endswith(suffix):
            return name[:-len(suffix)]
    return name

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Determine which classes are not superclasses of any other class in the list
    minimal = set()
    for cls in classes:
        if not any(issubclass(d, cls) and d is not cls for d in classes):
            minimal.add(cls)
    # Preserve the original order while keeping only the minimal classes
    return [cls for cls in classes if cls in minimal]

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    cls_dict = vars(self.__class__)
    if all:
        return [name for name, val in cls_dict.items() if not callable(val)]
    else:
        return [name for name, val in cls_dict.items()
                if not callable(val) and not name.startswith('_')]

def _c_optimizations_ignored(self):
    """The opposite of `_c_optimizations_required`."""
    return not self._c_optimizations_required()

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    self.context = {}
    if hasattr(self, 'initial_value') and self.initial_value is not None:
        self.bins = [self.initial_value] * len(self.bins)
    else:
        self.bins = self.make_bins()

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve the error indices for the given coordinate name from the
    # instance's error mapping. If the mapping is missing or the coordinate
    # is not present, return an empty list.
    err_map = getattr(self, 'err_indices', None)
    if err_map is None:
        return []
    return list(err_map.get(coord_name, []))

def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Reject if seq is a Source sequence
    if isinstance(seq, Source):
        return False

    # Direct FillRequest instance is OK
    if isinstance(seq, FillRequest):
        return True

    # Check for the presence of any FillRequest in an iterable sequence
    try:
        for item in seq:
            if isinstance(item, FillRequest):
                return True
    except TypeError:
        # seq is not iterable; already handled above
        pass

    return False

def is_run_el(obj):
    """Object contains executable method 'run'."""
    return hasattr(obj, 'run') and callable(getattr(obj, 'run'))

def is_fill_compute_el(obj):
    """Object contains executable methods 'fill' and 'compute'."""
    return callable(getattr(obj, 'fill', None)) and callable(getattr(obj, 'compute', None))

def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    if not isinstance(d1, dict) or not isinstance(d2, dict):
        raise TypeError("difference requires two dictionaries")

    # Import deepcopy lazily to avoid top-level import
    from copy import deepcopy

    def _diff(d1_local, d2_local, lev):
        result = {}
        for key, val in d1_local.items():
            if key not in d2_local:
                # Key missing in d2: include entire value
                if isinstance(val, dict):
                    # If we are allowed to recurse, deep copy the dict
                    if lev > 0 or lev == -1:
                        result[key] = deepcopy(val)
                    else:
                        # Return the subdict directly
                        result[key] = val
                else:
                    result[key] = deepcopy(val)
            else:
                val2 = d2_local[key]
                # Both values are dicts and we can recurse
                if isinstance(val, dict) and isinstance(val2, dict):
                    if lev > 0 or lev == -1:
                        sub_diff = _diff(val, val2, lev - 1 if lev != -1 else -1)
                        if sub_diff:
                            result[key] = sub_diff
                    else:
                        # At level 0, treat any difference as whole dict
                        result[key] = deepcopy(val)
                else:
                    # If values differ, include from d1
                    if val != val2:
                        result[key] = deepcopy(val)
        return result

    return _diff(d1, d2, level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    # Keys that should keep their original value when we are at the top level
    IDENTIFYING_KEYS = {"apiVersion", "kind", "metadata"}

    def _process_item(item):
        if isinstance(item, dict):
            return {k: _process_item(v) for k, v in item.items()}
        elif isinstance(item, list):
            # Recursively process list elements that are dicts, otherwise set to None
            return [_process_item(elem) if isinstance(elem, dict) else None for elem in item]
        else:
            # Non-dict, non-list: keep original only if we are at first level and key is identifying
            # The caller handles keeping values for identifying keys; otherwise None
            return None

    def _process_dict(d, top_level=False):
        result = {}
        for key, value in d.items():
            if isinstance(value, dict):
                result[key] = _process_dict(value, top_level=False)
            elif isinstance(value, list):
                # Process list elements
                result[key] = [_process_dict(item, top_level=False) if isinstance(item, dict) else None
                               for item in value]
            else:
                # Primitive value
                if top_level and key in IDENTIFYING_KEYS:
                    # Preserve original identifying field value
                    result[key] = value
                else:
                    result[key] = None
        return result

    return _process_dict(manifest_dict, top_level=first_level)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    if not hasattr(app, "spec") or not hasattr(app.spec, "manifest"):
        return

    for res in app.spec.manifest.values():
        # Skip if the resource already has an observer schema
        if getattr(res, "observer_schema", None) or res.get("observer_schema"):
            continue

        # Build a minimal default schema
        api_version = getattr(res, "apiVersion", None) or res.get("apiVersion", "v1")
        kind = getattr(res, "kind", None) or res.get("kind", "Resource")
        # Retrieve the name from metadata if possible
        if hasattr(res, "metadata") and isinstance(res.metadata, dict):
            name = res.metadata.get("name", None)
        else:
            name = res.get("metadata", {}).get("name", None)

        default_schema = {"apiVersion": api_version, "kind": kind}
        if name is not None:
            default_schema["metadata"] = {"name": name}

        # Attach the default schema back to the resource
        if isinstance(res, dict):
            res["observer_schema"] = default_schema
        else:
            setattr(res, "observer_schema", default_schema)

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    parts = []
    if hasattr(self, 'errors'):
        parts.append(f"{len(self.errors)} error(s)")
    if hasattr(self, 'warnings'):
        parts.append(f"{len(self.warnings)} warning(s)")
    if parts:
        return prefix + ", ".join(parts)
    return prefix + "no errors or warnings"

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Optional extraction of spec version from the type field
        if extract_spec_version:
            type_value = inventory.get('type')
            if isinstance(type_value, str):
                try:
                    # Assume a format like "FOLIA-1.0" or "FOLIA-2.0"
                    _, ver = type_value.split('-', 1)
                    # Basic validation: the version should be a float or a string that can be parsed as one
                    float(ver)  # will raise if not numeric
                    self.spec_version = ver
                except Exception:
                    # Ignore parsing errors – keep the existing spec_version
                    pass

        # Basic validation checks
        required_fields = ['id', 'content']
        for field in required_fields:
            if field not in inventory:
                raise ValueError(f"Missing required field '{field}' in inventory")

        # Validate that the id is a string
        if not isinstance(inventory['id'], str):
            raise TypeError("inventory 'id' must be a string")

        # Validate content based on the specification version
        if self.spec_version == '1.0':
            if not isinstance(inventory['content'], list):
                raise TypeError("inventory 'content' must be a list for spec version 1.0")
        else:
            # For other versions, allow a dict or list
            if not isinstance(inventory['content'], (list, dict)):
                raise TypeError(f"inventory 'content' must be a list or dict for spec version {self.spec_version}")

        return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Collect all digests reported in the manifest
    manifest_digests = set()
    for f in manifest_files:
        # Try to get the digest from a dict or an object attribute
        if isinstance(f, dict):
            digest = f.get('digest')
        else:
            digest = getattr(f, 'digest', None)
        if digest:
            manifest_digests.add(digest)

    # 1) Ensure each digest required by the manifest is actually used
    missing = manifest_digests - set(digests_used)
    if missing:
        raise ValueError(
            f"The following digests are listed in the manifest but not used: {sorted(missing)}"
        )

    # 2) Ensure there are no digests claimed as used that are not present in the manifest
    unused = set(digests_used) - manifest_digests
    if unused:
        raise ValueError(
            f"The following digests are used but not defined in the manifest: {sorted(unused)}"
        )

    # If both checks pass, everything is consistent
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("Fixity block must be a dictionary")

    required = ["file", "checksum"]
    for key in required:
        if key not in fixity:
            raise ValueError(f"Missing required key '{key}' in fixity block")

    file_name = fixity["file"]
    if file_name not in manifest_files:
        raise ValueError(f"File '{file_name}' referenced in fixity block is not present in the manifest")

def add_asset(self, basename, file_path):
    """
    "{
        "artigo02-gf03.tiff": "/path/artigo02-gf03.tiff",
        "artigo02-gf03.jpg": "/path/artigo02-gf03.jpg",
        "artigo02-gf03.png": "/path/artigo02-gf03.png",
    }
    """
    # Initialize the assets dictionary if it does not exist
    if not hasattr(self, 'assets') or not isinstance(self.assets, dict):
        self.assets = {}

    # Prevent duplicate asset names
    if basename in self.assets:
        raise ValueError(f"Asset '{basename}' already exists in self.assets.")

    # Store the file path under the given basename
    self.assets[basename] = file_path

    # Return the stored file path (optional)
    return self.assets[basename]

def fix_namespace_prefix_w(content):
    """
    Convert os textos cujo padrão é `w:st="` em `w-st="`
    """
    if not isinstance(content, str):
        raise TypeError("content must be a string")
    return content.replace('w:st="', 'w-st="')

def match_pubdate(node, pubdate_xpaths):
    """
    Retorna o primeiro match da lista de pubdate_xpaths
    """
    for xpath in pubdate_xpaths:
        results = node.xpath(xpath)
        if results:
            return results[0]
    return None

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = ' ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}:"]
    for name, value in vars(self).items():
        if name.startswith('_'):
            continue
        if hasattr(value, 'pretty') and callable(value.pretty):
            lines.append(value.pretty(indent + 2, debug))
        elif isinstance(value, list):
            lines.append(f"{indent_str}  {name}: [")
            for item in value:
                if hasattr(item, 'pretty') and callable(item.pretty):
                    lines.append(item.pretty(indent + 4, debug))
                else:
                    lines.append(f"{indent_str}    {repr(item)}")
            lines.append(f"{indent_str}  ]")
        else:
            lines.append(f"{indent_str}  {name}: {repr(value)}")
    if debug:
        lines.append(f"{indent_str}  (debug)")
    return '\n'.join(lines)

def absorb(self, args):
    """Given an `args` sequence of expressions, return a new list of expression
    applying absorption and negative absorption.

    See https://en.wikipedia.org/wiki/Absorption_law

    Absorption::

        A & (A | B) = A, A | (A & B) = A

    Negative absorption::

        A & (~A | B) = A & B, A | (~A & B) = A | B
    """
    # Helper functions -----------------------------------------------------
    def _contains(expr, target):
        """Return True if target is found inside expr."""
        if expr == target:
            return True
        # Binary expression
        if hasattr(expr, "op") and expr.op in ("and", "or"):
            return _contains(expr.left, target) or _contains(expr.right, target)
        # Negation
        if hasattr(expr, "op") and expr.op == "not":
            return _contains(expr.operand, target)
        return False

    def _compose_and(lhs, rhs):
        return Expr("and", lhs, rhs)

    def _compose_or(lhs, rhs):
        return Expr("or", lhs, rhs)

    def _compose_not(expr):
        return Expr("not", expr)

    # Combine two expressions according to absorption rules
    def _combine(a, b):
        # identical expressions
        if a == b:
            return a

        # A & (A | B)  or  (A | B) & A  -> A
        if a.op == "and" and b.op == "or" and (_contains(b.left, a) or _contains(b.right, a)):
            return a
        if b.op == "and" and a.op == "or" and (_contains(a.left, b) or _contains(a.right, b)):
            return b

        # A | (A & B)  or  (A & B) | A  -> A
        if a.op == "or" and b.op == "and" and (_contains(b.left, a) or _contains(b.right, a)):
            return a
        if b.op == "or" and a.op == "and" and (_contains(a.left, b) or _contains(a.right, b)):
            return b

        # Negative absorption: A & (~A | B) -> A & B
        if a.op == "and" and b.op == "or":
            # check for ~A on one side
            if hasattr(b.left, "op") and b.left.op == "not" and b.left.operand == a:
                return _compose_and(a, b.right)
            if hasattr(b.right, "op") and b.right.op == "not" and b.right.operand == a:
                return _compose_and(a, b.left)
        if b.op == "and" and a.op == "or":
            if hasattr(a.left, "op") and a.left.op == "not" and a.left.operand == b:
                return _compose_and(b, a.right)
            if hasattr(a.right, "op") and a.right.op == "not" and a.right.operand == b:
                return _compose_and(b, a.left)

        # Negative absorption: A | (~A & B) -> A | B
        if a.op == "or" and b.op == "and":
            if hasattr(b.left, "op") and b.left.op == "not" and b.left.operand == a:
                return _compose_or(a, b.right)
            if hasattr(b.right, "op") and b.right.op == "not" and b.right.operand == a:
                return _compose_or(a, b.left)
        if b.op == "or" and a.op == "and":
            if hasattr(a.left, "op") and a.left.op == "not" and a.left.operand == b:
                return _compose_or(b, a.right)
            if hasattr(a.right, "op") and a.right.op == "not" and a.right.operand == b:
                return _compose_or(b, a.left)

        # No absorption applicable
        return None

    # -----------------------------------------------------------------------
    # Main reduction loop
    remaining = list(args)
    changed = True
    while changed:
        changed = False
        new_remaining = []
        i = 0
        while i < len(remaining):
            a = remaining[i]
            combined = False
            # try to combine a with any of the later elements
            for j in range(i + 1, len(remaining)):
                b = remaining[j]
                result = _combine(a, b)
                if result is not None:
                    new_remaining.append(result)
                    # mark that a and b are consumed
                    del remaining[j]
                    del remaining[i]
                    changed = True
                    combined = True
                    break
            if not combined:
                new_remaining.append(a)
            i += 1
        remaining = new_remaining

    return remaining

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings.
    """
    def wrapper(*args, **kwargs):
        val = namefunc(*args, **kwargs)
        try:
            # In Python 2, unicode type is defined
            if isinstance(val, unicode):
                return val.encode('utf-8')
        except NameError:
            # In Python 3, unicode is not defined
            pass
        return val
    return wrapper

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to import the modern importlib.metadata (PEP 566)
    try:
        from importlib.metadata import version as _get_version, PackageNotFoundError
    except Exception:
        # For older Python versions install importlib-metadata
        try:
            from importlib_metadata import version as _get_version, PackageNotFoundError
        except Exception:
            # No import machinery available – fall back to a default
            return {"version": "0+unknown"}

    # Determine the top level package name from this module
    package = __name__.split('.')[0]
    try:
        # First attempt: use importlib.metadata
        return {"version": _get_version(package)}
    except PackageNotFoundError:
        # Second attempt: use pkg_resources if available
        try:
            from pkg_resources import get_distribution
            return {"version": get_distribution(package).version}
        except Exception:
            # Final fallback
            return {"version": "0+unknown"}}

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    output = []
    if style.lower() == 'html':
        for p in pieces:
            if hasattr(p, 'render_html'):
                output.append(p.render_html())
            else:
                output.append(str(p))
    elif style.lower() == 'text':
        for p in pieces:
            if hasattr(p, 'text'):
                output.append(p.text())
            else:
                output.append(str(p))
    else:
        for p in pieces:
            if hasattr(p, 'render'):
                output.append(p.render(style))
            else:
                output.append(str(p))
    return "".join(output)

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    # Check each piece to see if a plus already appears
    for piece in pieces:
        if '+' in piece:
            return '.'
    return '+'

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess
    import os

    if commands is None:
        raise ValueError("commands must not be None")

    # Build the command list
    if isinstance(commands, str):
        cmd = [commands]
    else:
        cmd = list(commands)

    # Append any additional args
    if args:
        cmd += list(args)

    if verbose:
        print(f"Running command: {' '.join(cmd)}")
        print(f"  cwd: {cwd}")
        print(f"  env: {env if env is not None else os.environ}")

    # Prepare the environment
    if env is not None:
        # Combine provided env with the current environment
        env_merged = os.environ.copy()
        env_merged.update(env)
    else:
        env_merged = None

    # Decide how to handle stderr
    if hide_stderr:
        stderr = subprocess.DEVNULL
    else:
        stderr = None

    # Execute the command
    try:
        completed = subprocess.run(
            cmd,
            cwd=cwd,
            env=env_merged,
            stdout=subprocess.PIPE,
            stderr=stderr,
            text=True,
            check=False
        )
    except FileNotFoundError as e:
        if verbose:
            print(f"Command not found: {cmd[0]}")
        raise e

    # Optionally print output if verbose
    if verbose and completed.stdout:
        print("Output:")
        print(completed.stdout)

    return completed

_vcs_handlers = {}

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not callable(method):
        raise TypeError("Handler must be callable")
    if vcs in _vcs_handlers:
        raise ValueError(f"Handler already registered for VCS '{vcs}'")
    _vcs_handlers[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0
    # Assume the object hierarchy can be traversed via an iterable,
    # e.g. the root provides an `iter_objects()` method.
    try:
        objects_iter = self.iter_objects()
    except AttributeError:
        # Fallback: iterate over children if no dedicated iterator
        objects_iter = iter(self)

    for obj in objects_iter:
        num_objects += 1
        is_valid = True

        if validate_objects:
            try:
                # The object itself should provide a validate method
                if hasattr(obj, "validate"):
                    obj.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Validation failed for object '{getattr(obj, 'id', repr(obj))}': {exc}")

        if check_digests and is_valid:
            try:
                # If the object provides a digest verification method
                if hasattr(obj, "verify_digest"):
                    obj.verify_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"[WARNING] Digest check failed for object '{getattr(obj, 'id', repr(obj))}': {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    def _parse_inventory(path):
        """Return a dict mapping file paths to their digests."""
        tree = ET.parse(path)
        root = tree.getroot()
        digests = {}
        # Assume the XML structure has <file path="..." digest="..."/> elements
        for file_el in root.findall('.//file'):
            fp = file_el.get('path')
            val = file_el.get('digest')
            if fp and val:
                digests[fp] = val
        return digests

    root_digests = None
    for idx, ver_dir in enumerate(version_dirs):
        inv_path = os.path.join(ver_dir, 'inventory.xml')
        if not os.path.exists(inv_path):
            raise FileNotFoundError(f"Missing inventory in version directory '{ver_dir}'")
        cur_digests = _parse_inventory(inv_path)

        if idx == 0:
            root_digests = cur_digests
            continue

        # Check that current inventory contains all files present up to this point
        missing = set(root_digests.keys()) - set(cur_digests.keys())
        if missing:
            raise ValueError(f"Inventory in '{ver_dir}' is missing files: {', '.join(missing)}")

        # Record any digest differences from the root inventory
        diffs = {}
        for key, root_val in root_digests.items():
            cur_val = cur_digests.get(key)
            if cur_val is None:
                continue
            if cur_val != root_val:
                diffs[key] = (root_val, cur_val)
        if diffs:
            raise ValueError(f"Digest differences in '{ver_dir}': {diffs}")

        # Update root_digests to include any new files since latest inventory
        for k, v in cur_digests.items():
            root_digests.setdefault(k, v)

    return True

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dict")
    if not bug_ids:
        return
    if isinstance(bug_ids, (list, tuple, set)):
        ids = ','.join(str(b) for b in bug_ids)
    else:
        ids = str(bug_ids)
    existing = params.get('ids')
    if existing:
        if isinstance(existing, str):
            params['ids'] = f"{existing},{ids}"
        else:
            params['ids'] = ids
    else:
        params['ids'] = ids

def deep_merge_nodes(nodes):
    """
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    """
    from collections import OrderedDict

    def merge_mapping_nodes(a, b):
        """
        Merge two MappingNodes a and b, where b is merged into a. Keys in b override or
        extend those in a. If a value for a key is itself a MappingNode in both a and b,
        merge them recursively.
        """
        a_list = a.value
        b_list = b.value

        # Prepare a dict of b items for quick lookup by key string
        b_dict = OrderedDict()
        for b_key_node, b_val_node in b_list:
            b_dict[b_key_node.value] = (b_key_node, b_val_node)

        result_list = []
        used_b_keys = set()

        # Iterate over a's items to preserve order
        for a_key_node, a_val_node in a_list:
            key = a_key_node.value
            if key in b_dict:
                b_key_node, b_val_node = b_dict[key]
                # Prefer key node from a (original)
                if isinstance(a_val_node, MappingNode) and isinstance(b_val_node, MappingNode):
                    merged_val = merge_mapping_nodes(a_val_node, b_val_node)
                else:
                    merged_val = b_val_node
                result_list.append((a_key_node, merged_val))
                used_b_keys.add(key)
            else:
                result_list.append((a_key_node, a_val_node))

        # Add remaining items from b that were not in a
        for key, (b_key_node, b_val_node) in b_dict.items():
            if key not in used_b_keys:
                result_list.append((b_key_node, b_val_node))

        # Preserve the tag from the original mapping node a
        return type(a)(tag=a.tag, value=result_list)

    merged_map = OrderedDict()

    for key_node, value_node in nodes:
        key = key_node.value
        if key in merged_map:
            existing_key_node, existing_value_node = merged_map[key]
            if isinstance(existing_value_node, type(value_node)):
                # If both values are MappingNode, deep merge them
                if isinstance(existing_value_node, ruamel.yaml.nodes.MappingNode):
                    merged_value = merge_mapping_nodes(existing_value_node, value_node)
                else:
                    # Non-mapping values: last value wins
                    merged_value = value_node
            else:
                merged_value = value_node
            merged_map[key] = (existing_key_node, merged_value)
        else:
            merged_map[key] = (key_node, value_node)

    return list(merged_map.values())

def parser_flags(parser):
    '''Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.'''
    flags = []
    for action in getattr(parser, "_actions", []):
        # action.option_strings may contain flags like ['-h', '--help']
        for opt in getattr(action, "option_strings", []):
            flags.append(opt)
    return " ".join(flags)

def parse_arguments(*arguments):
    """Given command-line arguments with which this script was invoked, parse the arguments and return
    them as an ArgumentParser instance."""
    import argparse
    parser = argparse.ArgumentParser()
    return parser.parse_args(arguments)

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    for action in parser._actions:
        # positional arguments typically have no option_strings
        if action.option_strings:
            flags.extend(action.option_strings)
    return ' '.join(flags)

def _dictsum(dicts):
    """Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    result = {}
    for d in dicts:
        for key, value in d.items():
            result[key] = result.get(key, 0) + value
    return result

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""
    if not url_args:
        return url

    import re

    def _repl(match):
        key = match.group(1)
        if key in url_args:
            return str(url_args[key])
        return match.group(0)

    # Replace {key} placeholders
    url = re.sub(r'\{([^{}]+)\}', _repl, url)
    # Replace %(key)s placeholders
    url = re.sub(r'%\(([^)]+)\)s', _repl, url)

    return url

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    if isinstance(val, str):
        return val.strip().lower() == 'none'
    return False

def parser_flags(parser):
    '''
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    '''
    flags = []
    seen = set()
    for action in parser._actions:
        for opt in action.option_strings:
            if opt and opt not in seen:
                seen.add(opt)
                flags.append(opt)
    return " ".join(flags) or ""

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number
    """
    for key, val in list(flow_params.items()):
        if key == register_value:
            flow_params[register_number] = val
            del flow_params[key]
        elif isinstance(val, dict):
            _replace_register(val, register_number, register_value)
        elif isinstance(val, list):
            for item in val:
                if isinstance(item, dict):
                    _replace_register(item, register_number, register_value)
    return flow_params

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    if not isinstance(value, str):
        raise TypeError('value must be a string')
    return value.replace('.', arg)

def string_to_int(string: str, alphabet: List[str]) -> int:
    """Convert a string to a number, using the given alphabet.

    The input is assumed to have the most significant digit first.
    """
    if not alphabet:
        raise ValueError("Alphabet must not be empty.")
    base = len(alphabet)
    # Create mapping from symbol to digit
    mapping = {symbol: idx for idx, symbol in enumerate(alphabet)}
    value = 0
    for ch in string:
        if ch not in mapping:
            raise ValueError(f"Character '{ch}' not found in alphabet.")
        value = value * base + mapping[ch]
    return value

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        return name
    # Strip matching leading/trailing quotes if present
    if len(name) >= 2 and name[0] == name[-1] and name[0] in ("'", '"'):
        return name[1:-1]
    return name.strip("'\"")

import datetime

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == "always"):
        return None

    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string, got {type(frequency).__name__}")

    parts = frequency.strip().split()
    if len(parts) < 2:
        raise ValueError(f"Cannot parse frequency: '{frequency}'")

    # Try to interpret the first part as a number
    try:
        number = int(parts[0])
    except ValueError:
        # Allow floats as well
        try:
            number = float(parts[0])
        except ValueError:
            raise ValueError(f"Cannot parse number in frequency: '{parts[0]}'")

    unit = ' '.join(parts[1:]).lower()

    unit_map = {
        'week': ('weeks', 1),
        'weeks': ('weeks', 1),
        'day': ('days', 1),
        'days': ('days', 1),
        'hour': ('hours', 1),
        'hours': ('hours', 1),
        'minute': ('minutes', 1),
        'minutes': ('minutes', 1),
        'second': ('seconds', 1),
        'seconds': ('seconds', 1),
    }

    if unit not in unit_map:
        raise ValueError(f"Unknown time unit in frequency: '{unit}'")

    kwarg_name, multiplier = unit_map[unit]
    kwargs = {kwarg_name: number}

    return datetime.timedelta(**kwargs)

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    if os.name != 'nt':
        return False
    ostype = os.environ.get('OSTYPE', '').lower()
    msystem = os.environ.get('MSYSTEM', '').lower()
    return ostype.startswith('msys') or msystem.startswith('mingw')

def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.'''
    if ':' in matcher:
        name, default = matcher.split(':', 1)
        name = name.strip()
        default = default.strip()
    else:
        name = matcher.strip()
        default = None
    value = os.getenv(name)
    if value is None:
        if default is not None:
            return default
        raise RuntimeError(f"Environment variable '{name}' is not defined and no default value provided.")
    return value

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if strip:
        pattern = pattern.strip()
    return re.compile(pattern)

import os
import shlex

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    def _run_single(cmd, cmd_args):
        env_dict = os.environ.copy()
        if env:
            env_dict.update(env)

        # Build command list
        if isinstance(cmd, (list, tuple)):
            cmd_list = list(cmd)
        else:
            cmd_list = shlex.split(str(cmd))

        # Add arguments
        if cmd_args:
            if isinstance(cmd_args, (list, tuple)):
                cmd_list.extend(cmd_args)
            else:
                cmd_list.append(str(cmd_args))

        if verbose:
            print("Running command:", ' '.join(shlex.quote(part) for part in cmd_list))

        try:
            result = subprocess.run(
                cmd_list,
                cwd=cwd,
                env=env_dict,
                stdout=subprocess.PIPE,
                stderr=subprocess.DEVNULL if hide_stderr else subprocess.PIPE,
                text=True,
                check=False
            )
        except Exception as exc:
            if verbose:
                print("Error executing command:", exc)
            raise

        if verbose and not hide_stderr:
            print("stdout:\n", result.stdout)
            print("stderr:\n", result.stderr)

        return result

    # If multiple commands are provided, run them sequentially
    if isinstance(commands, (list, tuple)) and not isinstance(commands, str):
        results = []
        for cmd in commands:
            results.append(_run_single(cmd, args))
        return results
    else:
        return _run_single(commands, args)

def is_ipv4(target):
    """ Test if IPv4 address or not """
    try:
        addr = ipaddress.ip_address(target)
    except ValueError:
        return False
    return isinstance(addr, ipaddress.IPv4Address)

def find_roots(
    graph: "Graph", prop: "URIRef", roots: Optional[Set["Node"]] = None
) -> Set["Node"]:
    """Find the roots in some sort of transitive hierarchy.

    find_roots(graph, rdflib.RDFS.subClassOf)
    will return a set of all roots of the sub-class hierarchy

    Assumes triple of the form (child, prop, parent), i.e. the direction of
    RDFS.subClassOf or SKOS.broader
    """
    if roots is None:
        roots = set()
    else:
        roots = set(roots)

    children: Set["Node"] = set()
    parents: Set["Node"] = set()

    for child, parent in graph.subject_objects(prop):
        children.add(child)
        parents.add(parent)

    for parent in parents:
        if parent not in children:
            roots.add(parent)

    return roots

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    if dumper is None:
        dumper = yaml.SafeDumper
    return yaml.dump(obj, Dumper=dumper, default_flow_style=False, allow_unicode=True)

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8. 
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
    return obj

@classmethod
def protocol_handlers(cls, protocol_version=None):
    """ Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    handlers = getattr(cls, "_PROTOCOL_HANDLERS", {})
    if protocol_version is None:
        return dict(handlers)
    if not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple")
    if protocol_version in handlers:
        return {protocol_version: handlers[protocol_version]}
    return {}

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    from collections.abc import Sequence

    # Treat strings, bytes, and bytearrays as their own sequences
    if isinstance(seq, (str, bytes, bytearray)):
        return seq, type(seq)

    # If seq is already a sequence (like list, tuple, set, etc.), use it directly
    if isinstance(seq, Sequence):
        return seq, type(seq)

    # For non-sequence iterables, materialise into a list
    try:
        seq = list(seq)
    except TypeError:
        # Fallback: return as is if it can't be converted to a list
        pass

    return seq, type(seq)

def scale(self, other=None, recompute=False):
        """Compute or set scale (integral of the histogram).

        If *other* is ``None``, return scale of this histogram.
        If its scale was not computed before,
        it is computed and stored for subsequent use
        (unless explicitly asked to *recompute*).
        Note that after changing (filling) the histogram
        one must explicitly recompute the scale
        if it was computed before.

        If a float *other* is provided, rescale self to *other*.

        Histograms with scale equal to zero can't be rescaled.
        :exc:`.LenaValueError` is raised if one tries to do that.
        """

        # Return current scale
        if other is None:
            if recompute or not hasattr(self, "_scale"):
                # Determine the underlying data of the histogram.
                # The histogram may be a list, tuple, array, or a more
                # specialized object exposing its values via .values()
                # or a .data attribute.  We try these in order.
                try:
                    values = list(self)
                except TypeError:
                    try:
                        values = self.values()
                    except AttributeError:
                        try:
                            values = self.data
                        except AttributeError:
                            raise RuntimeError("Unrecognized histogram data structure")

                self._scale = float(sum(values))
            return self._scale

        # Rescale: other must be a float (or convertible)
        new_total = float(other)
        current = self.scale(recompute=True)

        if current == 0:
            raise ValueError("Cannot rescale histogram with zero scale")

        factor = new_total / current

        # Apply factor to each bin.
        # The ordering and mutability of the histogram representation
        # may vary; we attempt a few common patterns.
        try:
            # Direct list/array style
            for i in range(len(self)):
                self[i] *= factor
        except (AttributeError, TypeError):
            try:
                # If histogram is stored in a list attribute named `hist`
                hist = self.hist
                for i in range(len(hist)):
                    hist[i] *= factor
                self.hist = hist
            except Exception:
                try:
                    # Try a mapping of bin->count
                    for key in self:
                        self[key] *= factor
                except Exception:
                    raise RuntimeError("Unsupported histogram structure for rescaling")

        self._scale = new_total
        return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine how to iterate over the histogram bins
    # First try an attribute that contains bin objects
    if hasattr(hist, "bins") and hasattr(hist, "contents") is False:
        bin_iter = hist.bins
    elif hasattr(hist, "edges") and hasattr(hist, "contents"):
        # typical numpy histogram representation
        edges = hist.edges
        contents = hist.contents
        bin_iter = list(zip(edges[:-1], edges[1:], contents))
    elif hasattr(hist, "__iter__"):
        # fallback: direct iterable of bin contents
        try:
            bin_iter = list(hist)
        except TypeError:
            raise ValueError("Unable to interpret histogram: no suitable bins or edges.")
    else:
        raise ValueError("Unable to interpret histogram: no suitable bins or edges.")

    points = []

    # Helper to compute coordinate from a bin object or edges
    def _coord_from_bin(bin_obj, edges, index):
        if get_coordinate == "left":
            return edges[index]
        elif get_coordinate == "right":
            return edges[index + 1]
        elif get_coordinate == "middle":
            return 0.5 * (edges[index] + edges[index + 1])
        else:
            raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")

    # Iterate over bins
    if hasattr(bin_iter[0] if bin_iter else None, "__iter__") and not isinstance(bin_iter[0], (int, float)):
        # bin_iter yielded a tuple like (xlow, xhigh, content)
        for idx, (xlow, xhigh, bin_content) in enumerate(bin_iter):
            # Determine coordinate
            if get_coordinate == "left":
                coord = xlow
            elif get_coordinate == "right":
                coord = xhigh
            elif get_coordinate == "middle":
                coord = 0.5 * (xlow + xhigh)
            else:
                raise ValueError("get_coordinate must be 'left', 'right' or 'middle'")
            # Determine value
            if make_value is None:
                value = bin_content
            else:
                value = make_value(bin_content)
            # Build point
            if isinstance(value, (list, tuple, set)):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)
    else:
        # bin_iter yielded bin objects or simple content
        # Try to handle both cases
        for idx, bin_obj in enumerate(bin_iter):
            # Determine coordinate
            coord = None
            if hasattr(bin_obj, "xmin") and hasattr(bin_obj, "xmax"):
                if get_coordinate == "left":
                    coord = bin_obj.xmin
                elif get_coordinate == "right":
                    coord = bin_obj.xmax
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.xmin + bin_obj.xmax)
            elif hasattr(bin_obj, "xlow") and hasattr(bin_obj, "xhigh"):
                if get_coordinate == "left":
                    coord = bin_obj.xlow
                elif get_coordinate == "right":
                    coord = bin_obj.xhigh
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.xlow + bin_obj.xhigh)
            elif hasattr(bin_obj, "edges") and len(bin_obj.edges) == 2:
                if get_coordinate == "left":
                    coord = bin_obj.edges[0]
                elif get_coordinate == "right":
                    coord = bin_obj.edges[1]
                elif get_coordinate == "middle":
                    coord = 0.5 * (bin_obj.edges[0] + bin_obj.edges[1])
            else:
                # Fallback: if histogram provided edges separately
                if hasattr(hist, "edges"):
                    edges = hist.edges
                    coord = _coord_from_bin(bin_obj, edges, idx)
            if coord is None:
                raise ValueError(f"Cannot determine coordinate for bin at index {idx}")
            # Determine value
            if make_value is None:
                if hasattr(bin_obj, "content"):
                    value = bin_obj.content
                else:
                    value = bin_obj
            else:
                if hasattr(bin_obj, "content"):
                    value = make_value(bin_obj.content)
                else:
                    value = make_value(bin_obj)
            # Build point
            if isinstance(value, (list, tuple, set)):
                point = (coord,) + tuple(value)
            else:
                point = (coord, value)
            points.append(point)

    # Determine graph scale
    if scale is True:
        scale = getattr(hist, "scale", None)
    elif scale is None:
        scale = getattr(hist, "scale", None)

    # Instantiate graph
    graph = Graph(field_names=field_names, scale=scale)
    for pt in points:
        graph.add_point(*pt)
    return graph

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """

    # Determine the class of the candidate (handle class objects and instances)
    candidate_class = candidate if isinstance(candidate, type) else type(candidate)

    # Iterate over attributes defined in the interface
    for name, attr in iface.__dict__.items():
        if name.startswith('_'):  # Skip private/internal attributes
            continue
        if callable(attr):
            # For methods, the candidate must provide a callable with the same name
            if not hasattr(candidate_class, name) or not callable(getattr(candidate_class, name)):
                if not tentative:
                    raise AttributeError(
                        f"Candidate does not implement required method '{name}' from interface '{iface.__name__}'")
                return False
        else:
            # For non-callable attributes, the candidate must have a compatible value
            if not hasattr(candidate_class, name):
                if not tentative:
                    raise AttributeError(
                        f"Candidate does not provide required attribute '{name}' from interface '{iface.__name__}'")
                return False

    return True

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if explicit_mc is not None:
        return explicit_mc

    # Gather metaclasses from bases
    metaclasses = []
    for b in bases:
        m = type(b)
        if m is not type:
            metaclasses.append(m)

    if not metaclasses:
        return type

    if len(set(metaclasses)) == 1:
        return metaclasses[0]

    # If multiple metaclasses, find the most derived that is a subclass of all others
    for m in metaclasses:
        if all(issubclass(m, other) for other in metaclasses):
            return m

    raise TypeError('metaclass conflict, no base class found that satisfies all given metaclasses')

def pop(self, key, default=__marker):
        """
        D.pop(k[,d]) -> v, remove specified key and return the corresponding value.
        If key is not found, d is returned if given, otherwise KeyError is raised.
        """
        if default is __marker:
            try:
                value = self[key]
            except KeyError:
                raise
            del self[key]
            return value
        else:
            try:
                value = self[key]
                del self[key]
                return value
            except KeyError:
                return default

def popitem(self):
    """Remove and return the `(key, value)` pair least recently used."""
    return super().popitem(last=False)

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('dictionary is empty')
    return super().popitem()

def _create_converter(self) -> _converting._Converter:
