def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    # Check for a public message indicator
    if getattr(request, "public_message", None):
        return True

    # Check for a private message indicator
    if getattr(request, "private_message", None):
        return True

    # Check for a legacy payload indicator
    if getattr(request, "legacy_payload", None):
        return True

    # Additional heuristic: look for a specially formatted payload string
    if hasattr(request, "payload") and isinstance(request.payload, (str, bytes)):
        payload = request.payload.lower() if isinstance(request.payload, str) else request.payload.decode("utf-8", "ignore").lower()
        if "diaspora" in payload:
            return True

    # No indicators found
    return False

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    # a Matrix request generally contains a path beginning with "/_matrix"
    # and uses JSON content types
    try:
        path = getattr(request, "path", getattr(request, "url", ""))
        if isinstance(path, str):
            # strip query string if present
            path = path.split("?", 1)[0]
    except Exception:
        return False

    if path.startswith("/_matrix"):
        return True

    # fall back to checking headers if path is not available
    if hasattr(request, "headers"):
        accept = request.headers.get("Accept", "")
        content_type = request.headers.get("Content-Type", "")
        if "application/json" in accept or content_type.startswith("application/json"):
            return True

    return False

def format_dt(dt):
    """
    Format a datetime in the way that D* nodes expect.
    """
    # If the datetime is timezone-aware, use ISO 8601 format without colon in offset
    if dt.tzinfo is not None:
        # `strftime` with `%z` gives offset as ±HHMM, which is acceptable for D* nodes
        return dt.strftime('%Y-%m-%dT%H:%M:%S%z')
    # For naive datetimes assume UTC and append 'Z'
    return dt.strftime('%Y-%m-%dT%H:%M:%SZ')

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if not isinstance(text, str):
        return text
    # Regular expression to find URLs or email addresses
    pattern = re.compile(
        r'''(?i)\b(
            (?: https?:// | www\d{0,3}[.] | mailto: )   # protocol
            [^\s<>]+                                   # domain & path
        )'''
    )

    def replace(match):
        url = match.group(0)
        # Ensure href has a protocol
        if url.startswith('www.'):
            href = 'http://' + url
        else:
            href = url if url.startswith(('http://', 'https://', 'mailto:')) else 'http://' + url
        # Return an <a> tag with desired attributes
        return (
            f'<a href="{href}" '
            f'target="_blank" rel="nofollow noreferrer" '
            f'class="linkified">{url}</a>'
        )

    # Substitute all detected links with the formatted <a> tags
    return pattern.sub(replace, text)

def fetch_content_type(url: str) -> Optional[str]:
    import urllib.request
    import urllib.error
    try:
        # Send a HEAD request to obtain only headers
        req = urllib.request.Request(url, method='HEAD')
        with urllib.request.urlopen(req) as resp:
            # urllib returns a mapping-like object for headers
            return resp.headers.get('Content-Type')
    except (urllib.error.HTTPError, urllib.error.URLError):
        # Any error while fetching means we cannot determine the content type
        return None
    except Exception:
        # Fallback for unforeseen errors
        return None

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    if not tag:
        return False
    for c in tag:
        if not (c.isalnum() or c in {'-','_'}):
            return False
    return True

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    result = {}
    for child in node:
        result[child.tag] = child
    return result

def get_nodeinfo_well_known_document(url, document_path=None):
    """
    Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Try to load a custom document if a path is supplied
    if document_path:
        try:
            with open(document_path, 'r', encoding='utf-8') as f:
                import json
                return json.load(f)
        except Exception:
            # Fall back to default if loading fails
            pass

    # Normalise the URL (remove any trailing slash)
    clean_url = url.rstrip('/')

    # Default NodeInfo structure according to the spec
    return {
        "schema": "http://nodeinfo.diaspora.software/ns/schema/1.0",
        "software": {
            "name": "Example",
            "version": "1.0",
            "homepage": clean_url
        },
        "protocols": ["activitypub"],
        "interfaces": ["altids", "collections"],
        "services": {}
    }

def parse_diaspora_webfinger(document: str) -> Dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    import json
    import xml.etree.ElementTree as ET

    # Attempt JSON parsing first
    try:
        data = json.loads(document)
    except ValueError:
        # Fall back to XRD (XML) parsing
        try:
            root = ET.fromstring(document)
        except ET.ParseError as exc:
            raise ValueError("Input is neither valid JSON nor XRD XML") from exc

        def strip_ns(tag):
            return tag.split('}', 1)[-1] if '}' in tag else tag

        subject = None
        aliases = []
        links = []

        for child in root:
            tag = strip_ns(child.tag)
            if tag == 'Subject':
                subject = child.text
            elif tag == 'Alias':
                aliases.append(child.text)
            elif tag == 'Link':
                rel = child.attrib.get('rel')
                link_type = None
                href = None
                for sub in child:
                    subtag = strip_ns(sub.tag)
                    if subtag == 'Type':
                        link_type = sub.text
                    elif subtag == 'Href':
                        href = sub.text
                links.append({'rel': rel, 'type': link_type, 'href': href})

        data = {
            'subject': subject,
            'aliases': aliases,
            'links': links
        }

    # Ensure required keys exist
    subject = data.get('subject')
    aliases = data.get('aliases', [])
    links = data.get('links', [])

    return {
        'subject': subject,
        'aliases': aliases,
        'links': links
    }

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    from xml.etree import ElementTree as ET

    url = f"https://{host}/.well-known/xrd.xml"
    try:
        with urllib.request.urlopen(url, timeout=10) as response:
            data = response.read()
    except urllib.error.URLError as exc:
        raise RuntimeError(f"Failed to retrieve host-meta from {host!r}: {exc}") from exc

    try:
        return ET.fromstring(data)
    except ET.ParseError as exc:
        raise ValueError(f"Invalid XML received from {host!r}") from exc

