def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files. """
    if not isinstance(parser_dict, dict):
        return parser_dict

    # Process any top‑level "include" key
    inc = parser_dict.pop('include', None)

    # If no include directive, nothing to do
    if inc is None:
        return parser_dict

    # If the include value is a dict, merge it directly
    if isinstance(inc, dict):
        for key, val in inc.items():
            if key not in parser_dict:
                parser_dict[key] = val
            else:
                # Merge nested dictionaries
                if isinstance(parser_dict[key], dict) and isinstance(val, dict):
                    parser_dict[key].update(val)
                else:
                    # Overwrite non‑dict values
                    parser_dict[key] = val

    # If the include value is a list, each entry might be a file path or a nested dict
    elif isinstance(inc, list):
        for entry in inc:
            if isinstance(entry, str):
                # Treat the string as a file path to another spec file
                try:
                    with open(entry, "r", encoding="utf-8") as f:
                        inc_dict = json.load(f)
                except Exception as e:
                    # If the file cannot be read, skip it but keep a trace
                    _log_error("Failed to include spec file '%s': %s", entry, e)
                    continue
                # Recursively resolve includes in the loaded dictionary
                self._include_groups(inc_dict)
                # Merge the loaded dictionary into the current one
                for key, val in inc_dict.items():
                    if key not in parser_dict:
                        parser_dict[key] = val
                    else:
                        if isinstance(parser_dict[key], dict) and isinstance(val, dict):
                            parser_dict[key].update(val)
                        else:
                            parser_dict[key] = val

            elif isinstance(entry, dict):
                # Direct nested dict; merge it
                for key, val in entry.items():
                    if key not in parser_dict:
                        parser_dict[key] = val
                    else:
                        if isinstance(parser_dict[key], dict) and isinstance(val, dict):
                            parser_dict[key].update(val)
                        else:
                            parser_dict[key] = val

    # Return the modified dictionary (in‑place changes are also made)
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    # Start with defaults defined in the element's spec (if any)
    defaults = {}
    spec = getattr(self, "spec", None)
    if spec:
        # The spec could be a dict or an object with a defaults attribute
        if isinstance(spec, dict):
            defaults.update(spec.get("defaults", {}))
        elif hasattr(spec, "defaults"):
            defaults.update(spec.defaults)

    # Merge any defaults that are set on the element itself via a 'default_args' attribute
    if hasattr(self, "default_args") and isinstance(self.default_args, dict):
        defaults.update(self.default_args)

    # Potentially look for defaults provided by a global configuration or environment variables
    # For example, if a global CONFIG has defaults for this element type
    global_cfg = getattr(self, "_global_config", None)
    if global_cfg and isinstance(global_cfg, dict):
        cfg_defaults = global_cfg.get(self.__class__.__name__, {})
        if isinstance(cfg_defaults, dict):
            defaults.update(cfg_defaults)

    return defaults

def get_deprecated_args(self):
    """Returning dict with options which deprecate others."""
    return {}

def validate_arg_deprecation(self, cli_args, answer_file_args):
    """Validates and prints the deprecated arguments.

    :param cli_args: the dict of arguments from cli
    :param answer_file_args:  the dict of arguments from files
    """
    # ``deprecated_args`` is expected to be a list or set of argument names
    # that are considered deprecated.  If such an attribute does not exist,
    # simply do nothing.
    deprecated = getattr(self, "deprecated_args", set())

    # Check CLI arguments
    for arg in cli_args:
        if arg in deprecated:
            msg = f"Argument '{arg}' is deprecated and used via CLI."
            if arg in answer_file_args:
                msg += " It is also set in an answer file."
            print(msg)

    # Check answer file arguments that were not overridden by CLI
    for arg in answer_file_args:
        if arg in deprecated and arg not in cli_args:
            print(f"Argument '{arg}' is deprecated and used via answer file.")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # If a parser is attached, delegate to it
    if hasattr(self, 'parser'):
        return self.parser.get_parser_option_specs(command_name)
    # Fallback to a local mapping if present
    return getattr(self, '_parser_option_specs', {}).get(command_name, [])

def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name. """
        assert isinstance(command_name, str)
        assert isinstance(argument_name, str)
        try:
            command = self.commands[command_name]
        except KeyError:
            raise KeyError(f"Command '{command_name}' not found.")
        try:
            spec = command.options[argument_name]
        except KeyError:
            raise KeyError(f"Option '{argument_name}' not found in command '{command_name}'.")
        return spec

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    # Determine the dict-like representation of args
    if hasattr(args, "__dict__"):
        data = vars(args)
    elif isinstance(args, dict):
        data = args
    else:
        # Collect non-callable attributes that do not start with an underscore
        data = {k: getattr(args, k) for k in dir(args) if not k.startswith('_') and not callable(getattr(args, k))}
    # Return the keys whose values are None (i.e., silenced arguments)
    return [k for k, v in data.items() if v is None]

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not hasattr(self, 'REQUIRED_ARGS') or not self.REQUIRED_ARGS:
        return

    if not isinstance(args, dict):
        raise TypeError("args must be a dictionary")

    missing = [arg for arg in self.REQUIRED_ARGS if arg not in args]
    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
            condition
    """
    required = []
    for opt in options_spec:
        # Each option spec is expected to be a dict containing at least 'name'
        if not isinstance(opt, dict):
            continue
        name = opt.get('name')
        if not name:
            continue

        cond = opt.get('required_when')
        if cond is None:
            continue

        # Conditional can be a callable, a tuple/list of (arg, value) pairs,
        # or a simple argument name/value that determines if this option
        # is required.
        matched = False
        try:
            if callable(cond):
                matched = bool(cond(args))
            elif isinstance(cond, (list, tuple)):
                # Each element is expected to be a pair (arg_name, expected_value)
                matched = all(args.get(pair[0]) == pair[1] for pair in cond
                              if isinstance(pair, (list, tuple)) and len(pair) == 2)
            else:
                # Treat cond as a key whose presence/ truthiness in args
                # indicates requirement.
                matched = bool(args.get(cond))
        except Exception:
            matched = False

        if matched:
            required.append(name)
    return required

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments as an iterable of tuples
                 (arg_name, max_length, value). ``max_length`` can be None
                 to indicate no limit.
    """
    for arg_info in args:
        # Expect each item to be a tuple of (name, max_length, value)
        try:
            name, max_len, value = arg_info
        except Exception as exc:
            raise TypeError(f"Each argument specification must be a tuple of "
                            f"(arg_name, max_length, value). Got: {arg_info!r}") from exc

        # Skip if there is no maximum length or the value is None
        if max_len is None or value is None:
            continue

        # Only enforce length on objects that support ``len``
        try:
            current_len = len(value)
        except TypeError:
            # The value does not have a length, ignore this check
            continue

        if current_len > max_len:
            raise ValueError(f"Argument '{name}' has length {current_len}, "
                             f"which exceeds the allowed maximum of {max_len}.")

