def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        if not args:
            return

        # The class is expected to provide a mapping of argument names to their
        # allowed choices (e.g. self.arg_choices).  If it doesn't exist we simply
        # skip validation.
        choices_map = getattr(self, "arg_choices", {})

        for arg, value in args.items():
            if value is None:
                continue

            # Skip arguments that have no defined choice restrictions
            if arg not in choices_map:
                continue

            allowed = choices_map[arg]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value '{value}' for argument '{arg}'. "
                    f"Expected one of: {allowed}"
                )

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)
    for i, v in enumerate(args):
        if min_val is not None and v < min_val:
            raise ValueError(f"Argument {i} ({v}) is less than minimum {min_val}")
        if max_val is not None and v > max_val:
            raise ValueError(f"Argument {i} ({v}) is greater than maximum {max_val}")
    return True

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        if args is None:
            return {}, {}
        # Ensure we are dealing with a mapping
        if not isinstance(args, dict):
            if hasattr(args, 'items'):
                args = dict(args)
            else:
                raise ValueError("args must be a dict or a mapping")
        # Separate control arguments (starting with underscore) from nested
        control_args = {k: v for k, v in args.items() if str(k).startswith('_')}
        nested_args = {k: v for k, v in args.items() if not str(k).startswith('_')}
        return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not extra_vars:
        return vars_dict

    # If extra_vars is a dict, just update
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        # Otherwise iterate over each element
        for item in extra_vars:
            if isinstance(item, dict):
                vars_dict.update(item)
            else:
                # Expect a key, value pair
                try:
                    key, val = item
                except Exception as exc:
                    raise TypeError(
                        "Each item in extra_vars must be a dict or a key-value pair") from exc
                vars_dict[key] = val

    return vars_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Explicit conversion rules for known parsers/arguments
    # This mapping can be extended as needed.
    _CONVERSION_MAP = {
        'main': {
            'timeout': int,
            'verbose': lambda v: v.lower() in ('1', 'true', 'yes'),
            'threshold': float,
        },
        'virsh': {
            'memory': int,
            'memory_optimized': lambda v: v.lower() == 'yes',
        },
        'ospd': {
            'threads': int,
            'debug': lambda v: v.lower() in ('yes', 'true', 'on'),
        },
    }

    # Helper to detect JSON-like values
    def _try_parse_json(val):
        if not isinstance(val, str):
            return val
        try:
            import json
            return json.loads(val)
        except Exception:
            return val

    converters = _CONVERSION_MAP.get(parser_name, {})

    for key, val in list(values_dict.items()):
        # Skip if value is already not a string or None
        if val is None or not isinstance(val, str):
            continue

        # Use explicit converter if defined
        conv = converters.get(key)
        if conv is not None:
            try:
                values_dict[key] = conv(val)
            except Exception:
                # Leave original string if conversion fails
                pass
            continue

        # Heuristic conversions
        val_lower = val.lower()
        # Boolean
        if val_lower in ('true', 'false', 'yes', 'no', '1', '0'):
            values_dict[key] = val_lower in ('true', 'yes', '1')
            continue

        # Numeric
        try:
            # Try integer first
            int_val = int(val)
            values_dict[key] = int_val
            continue
        except ValueError:
            pass
        try:
            float_val = float(val)
            values_dict[key] = float_val
            continue
        except ValueError:
            pass

        # JSON-like structure
        parsed = _try_parse_json(val)
        if parsed != val:
            values_dict[key] = parsed
            continue

        # If none matched, keep original string
    # The method modifies values_dict in place; no explicit return required.

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_path = os.path.join(plugin_dir, 'plugin.json')
    if not os.path.isfile(spec_path):
        raise FileNotFoundError(f'Could not find plugin.json in {plugin_dir}')

    with open(spec_path, 'r', encoding='utf-8') as f:
        spec = json.load(f)

    def _flatten(obj, prefix=''):
        result = {}
        for key, value in obj.items():
            new_key = f'{prefix}.{key}' if prefix else key
            if isinstance(value, dict):
                result.update(_flatten(value, new_key))
            else:
                result[new_key] = value
        return result

    return _flatten(spec)

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    if not isinstance(path, str) or not isinstance(root, str):
        raise TypeError("path and root must be strings")
    # Normalise root: remove trailing slash (except when root is just '/')
    if root != '/' and root.endswith('/'):
        root = root.rstrip('/')
    # Check that the path starts with the root
    if not path.startswith(root):
        raise ValueError(f"Root '{root}' not found in path '{path}'")
    # Strip the root and any leading slash from the remaining path
    stripped = path[len(root):].lstrip('/')
    return stripped
